fn op_add32(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u32::try_from(args[0].int()).expect("argument 0 of add32 fits u32");
    let p1 = u32::try_from(args[1].int()).expect("argument 1 of add32 fits u32");
    let fault = fault_for("add32", fault);
    let r = match fault {
            Fault::SaturateAdd => p0.saturating_add(p1),
            Fault::TrapAsZeroAdd => p0.checked_add(p1).unwrap_or(0),
            _ => add32(p0, p1),
        };
        let r = match fault {
            Fault::NarrowWidth => (r as u16) as u32,
            _ => r,
        };
    V::Fixed(F::U32, r as i128)
}

fn op_sub8(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u8::try_from(args[0].int()).expect("argument 0 of sub8 fits u8");
    let p1 = u8::try_from(args[1].int()).expect("argument 1 of sub8 fits u8");
    let fault = fault_for("sub8", fault);
    let r = match fault {
            Fault::SaturateSub => p0.saturating_sub(p1),
            Fault::TrapAsZeroSub => p0.checked_sub(p1).unwrap_or(0),
            _ => sub8(p0, p1),
        };
    V::Fixed(F::U8, r as i128)
}

fn op_mul16(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u16::try_from(args[0].int()).expect("argument 0 of mul16 fits u16");
    let p1 = u16::try_from(args[1].int()).expect("argument 1 of mul16 fits u16");
    let fault = fault_for("mul16", fault);
    let r = match fault {
            Fault::SaturateMul => p0.saturating_mul(p1),
            Fault::TrapAsZeroMul => p0.checked_mul(p1).unwrap_or(0),
            _ => mul16(p0, p1),
        };
        let r = match fault {
            Fault::NarrowWidth => (r as u8) as u16,
            _ => r,
        };
    V::Fixed(F::U16, r as i128)
}

fn op_lt_i32(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = i32::try_from(args[0].int()).expect("argument 0 of lt_i32 fits i32");
    let p1 = i32::try_from(args[1].int()).expect("argument 1 of lt_i32 fits i32");
    let fault = fault_for("lt_i32", fault);
    let p0 = if fault == Fault::SignConfuse { let p = p0; p ^ i32::MIN } else { p0 };
    let p1 = if fault == Fault::SignConfuse { let p = p1; p ^ i32::MIN } else { p1 };
    let r = match fault {
            _ => lt_i32(p0, p1),
        };
    V::Bool(r)
}

fn op_try_u8(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = i16::try_from(args[0].int()).expect("argument 0 of try_u8 fits i16");
    let fault = fault_for("try_u8", fault);
    let r = match fault {
            _ => try_u8(p0),
        };
        let r = match fault {
            Fault::OffByOneRange => if r.is_none() && (p0 as i128 == u8::MAX as i128 + 1 || p0 as i128 == u8::MIN as i128 - 1) { Some(p0 as u8) } else { r },
            _ => r,
        };
    V::Opt(r.map(|x| Box::new(V::Fixed(F::U8, x as i128))))
}

fn op_shl16(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u16::try_from(args[0].int()).expect("argument 0 of shl16 fits u16");
    let p1 = u32::try_from(args[1].int()).expect("argument 1 of shl16 fits u32");
    let fault = fault_for("shl16", fault);
    let p1 = if fault == Fault::ShiftMask { let p = p1; p % 16 } else { p1 };
    let r = match fault {
            Fault::ShiftUb => if p1 >= 16 { p0 } else { shl16(p0, p1) },
            _ => shl16(p0, p1),
        };
    V::Fixed(F::U16, r as i128)
}

fn op_sar8(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = i8::try_from(args[0].int()).expect("argument 0 of sar8 fits i8");
    let p1 = u32::try_from(args[1].int()).expect("argument 1 of sar8 fits u32");
    let fault = fault_for("sar8", fault);
    let p1 = if fault == Fault::ShiftMask { let p = p1; p % 8 } else { p1 };
    let r = match fault {
            Fault::SarAsShr => if p1 >= 8 { 0 } else { ((p0 as u8) >> p1) as i8 },
            _ => sar8(p0, p1),
        };
    V::Fixed(F::I8, r as i128)
}

fn op_rotl32(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u32::try_from(args[0].int()).expect("argument 0 of rotl32 fits u32");
    let p1 = u32::try_from(args[1].int()).expect("argument 1 of rotl32 fits u32");
    let fault = fault_for("rotl32", fault);
    let r = match fault {
            Fault::RotateAsShiftLeft => if p1 >= 32 { 0 } else { p0 << p1 },
            _ => rotl32(p0, p1),
        };
    V::Fixed(F::U32, r as i128)
}

fn op_rotr16(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = u16::try_from(args[0].int()).expect("argument 0 of rotr16 fits u16");
    let p1 = u32::try_from(args[1].int()).expect("argument 1 of rotr16 fits u32");
    let fault = fault_for("rotr16", fault);
    let r = match fault {
            Fault::RotateAsShiftRight => if p1 >= 16 { 0 } else { ((p0 as u16) >> p1) as u16 },
            _ => rotr16(p0, p1),
        };
    V::Fixed(F::U16, r as i128)
}

fn op_popcnt8(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = i8::try_from(args[0].int()).expect("argument 0 of popcnt8 fits i8");
    let fault = fault_for("popcnt8", fault);
    let r = match fault {
            Fault::PopcountOff => ((p0 as u8) & (u8::MAX >> 1)).count_ones(),
            _ => popcnt8(p0),
        };
    V::Int(r as i128)
}

fn op_narrow8(_w: &[u64], args: &[V], fault: Fault) -> V {
    let p0 = i32::try_from(args[0].int()).expect("argument 0 of narrow8 fits i32");
    let fault = fault_for("narrow8", fault);
    match contained(|| {
        let r = match fault {
            _ => narrow8(p0),
        };
        r
    }) {
        Some(r) => V::Ok(Box::new(V::Fixed(F::I8, r as i128))),
        None if fault == Fault::MissingError => V::Ok(Box::new(V::Fixed(F::I8, 0 as i128))),
        None => V::Err("OUT_OF_RANGE".into()),
    }
}

